reference.LowerBound:
p := 0;
while p < |a| && a[p] < x
  invariant 0 <= p <= |a|
  invariant forall i :: 0 <= i < p ==> a[i] < x
  decreases |a| - p
{
  p := p + 1;
}
if p < |a| {
  assert forall i :: p <= i < |a| ==> a[p] <= a[i];
}

reference.Locate:
var p := LowerBound(a, x);
if p < |a| && a[p] == x {
  found := true;
  index := p;
} else {
  found := false;
  index := -1;
}

bodies.Locate:
var p := LowerBound(a, x);
found := true;
index := p;
